using System;
using System.IO;
using System.Reflection;
using System.Runtime.InteropServices;
using Avalonia;

namespace GnollHackM;

/* Entry point of the Avalonia desktop target; AvaloniaApp is generated by Avalonia.Controls.Maui */
internal static class AvaloniaDesktopProgram
{
    private const string WinCompositionArgument = "--win-composition=";
    private const string WinCompositionVariable = "GNOLLHACK_WIN_COMPOSITION";
    private const string WinGpuArgument = "--win-gpu=";
    private const string WinGpuVariable = "GNOLLHACK_WIN_GPU";
    /* Past the detector's own recheck interval, so that the second log line reflects a new check */
    private const int SteamOverlayRecheckMs = GHAvaloniaSteamOverlay.RecheckIntervalMs + 1000;

    private static string[] _args = Array.Empty<string>();
    private static System.Threading.Timer _steamOverlayRecheck = null;

    [STAThread]
    public static int Main(string[] args)
    {
        _args = args ?? Array.Empty<string>();
#if WINDOWS_AVALONIA
        /* Before anything loads gnollhackwin.dll, whose static CRT takes the standard handles when it loads */
        GHWindowsStderrLog.Install();
        if (!GHAvaloniaInstanceLock.TryAcquire())
        {
            GHAvaloniaInstanceLock.ReportAlreadyRunning();
            return 0;
        }
#endif
#if LINUX
        /* CEF starts its renderer, GPU and utility processes from this executable; they exit here, before anything
           else of the game is initialized */
        if (GHCefSubprocess.IsSubprocess(args))
            return GHCefSubprocess.Run(args);
        // WORKAROUND(WA-SKIASHARP-0009): libHarfBuzzSharp binds its own calls to the system HarfBuzz
        PreloadHarfBuzzSharp();
        if (!GHAvaloniaInstanceLock.TryAcquire())
        {
            GHAvaloniaInstanceLock.ReportAlreadyRunning();
            return 0;
        }
        GHAvaloniaShutdown.RegisterSignals();
        GHAvaloniaFontConfig.Install();
#endif
#if MACOS
        GHMacStderrLog.Install();
        if (!GHAvaloniaInstanceLock.TryAcquire())
        {
            GHAvaloniaInstanceLock.ReportAlreadyRunning();
            return 0;
        }
        GHAvaloniaShutdown.RegisterSignals();
#endif
        if (OperatingSystem.IsLinux())
            NativeLibrary.SetDllImportResolver(typeof(AvaloniaDesktopProgram).Assembly, ResolveLinuxLibrary);
        else if (OperatingSystem.IsMacOS())
            NativeLibrary.SetDllImportResolver(typeof(AvaloniaDesktopProgram).Assembly, ResolveMacLibrary);
        int exitCode = BuildAvaloniaApp().StartWithClassicDesktopLifetime(args);
        /* The lifetime can end with a game running, for example when the desktop session ends */
        GHAvaloniaShutdown.SaveGameBeforeExit();
#if WINDOWS_AVALONIA
        GnollHackX.GHApp.RevertScreenResolution();
#endif
#if LINUX
        GHCefRuntime.ShutdownIfInitialized();
#endif
        /* Explicit: the parked game thread is a foreground thread and would keep the process alive */
        Environment.Exit(exitCode);
        return exitCode;
    }

    /* X11: GLX with a software fallback, no Vulkan; popups drawn inside the window; WM_CLASS "GnollHack", which
       a desktop entry matches with StartupWMClass. macOS: GetMacRenderingModes, from the Metal Rendering setting;
       popups drawn inside the window; GHMacApplicationMenu instead of Avalonia's default application menu items.
       GPU resource budget: 2 GiB on macOS, where Metal needs about 1.3 GB on some levels, and 1.5 GiB elsewhere, where
       OpenGL needs about 0.7 GB; a full cache re-uploads textures every frame. */
    public static AppBuilder BuildAvaloniaApp()
    {
        AppBuilder builder = AppBuilder.Configure<AvaloniaApp>()
            .UsePlatformDetect()
            .WithInterFont()
            .LogToTrace()
            .With(new X11PlatformOptions
            {
                RenderingMode = new[] { X11RenderingMode.Glx, X11RenderingMode.Software },
                OverlayPopups = true,
                WmClass = "GnollHack",
            })
            .With(new AvaloniaNativePlatformOptions
            {
                RenderingMode = GetMacRenderingModes(),
                OverlayPopups = true,
            })
            .With(new MacOSPlatformOptions { DisableDefaultApplicationMenuItems = true })
            .With(new SkiaOptions { MaxGpuResourceSizeBytes = (OperatingSystem.IsMacOS() ? 2048L : 1536L) * 1024 * 1024 });
#if MACOS
        /* Registered before Avalonia.Native's own callback, which reads the application name */
        builder = builder.AfterSetup(GHMacApplicationMenu.Install);
#endif
        if (OperatingSystem.IsWindows())
        {
            string mode = GetRequestedWinComposition();
            string gpu = GetRequestedWinGpu();
            Win32PlatformOptions win32Options = CreateWin32PlatformOptions(mode);
#if WINDOWS_AVALONIA
            win32Options = AddGpuSelection(win32Options, gpu);
#endif
            if (win32Options != null)
                builder = builder.With(win32Options);
            builder = builder.AfterSetup(b => LogWindowsGraphics(mode, gpu));
        }
        return builder;
    }

    /* --win-gpu=<mode>, else GNOLLHACK_WIN_GPU; null for the default */
    private static string GetRequestedWinGpu()
    {
        foreach (string arg in _args)
        {
            if (arg != null && arg.StartsWith(WinGpuArgument, StringComparison.OrdinalIgnoreCase))
                return arg.Substring(WinGpuArgument.Length).Trim().ToLowerInvariant();
        }
        string variable = Environment.GetEnvironmentVariable(WinGpuVariable);
        return string.IsNullOrWhiteSpace(variable) ? null : variable.Trim().ToLowerInvariant();
    }

    /* --win-composition=<mode>, else GNOLLHACK_WIN_COMPOSITION; null for the default */
    private static string GetRequestedWinComposition()
    {
        foreach (string arg in _args)
        {
            if (arg != null && arg.StartsWith(WinCompositionArgument, StringComparison.OrdinalIgnoreCase))
                return arg.Substring(WinCompositionArgument.Length).Trim().ToLowerInvariant();
        }
        string variable = Environment.GetEnvironmentVariable(WinCompositionVariable);
        return string.IsNullOrWhiteSpace(variable) ? null : variable.Trim().ToLowerInvariant();
    }

    /* Windows composition. The default, for no mode or an unknown one, is an HWND flip-model swap chain paced by
       vblank (LowLatencyDxgiSwapChain), falling back to WinUI composition and then the window's redirection surface,
       with ANGLE. The modes, for testing: winui, dcomp, dxgi (the swap chain without the WinUI fallback), redirect (the
       redirection surface, paced by a sleep loop), wgl (OpenGL on the redirection surface), and avalonia, which
       returns null for Avalonia's own defaults. The other modes fall back to the redirection surface, and every one
       draws popups inside the window. The GPU mode, from --win-gpu=<mode> else GNOLLHACK_WIN_GPU, is independent of
       these: AddGpuSelection adds GHWindowsGpuSelection's adapter callback, to new options at Avalonia's defaults when
       this returns null, for auto (the default, also for an unknown mode: the high-performance adapter unless the
       Windows per-app preference is Power saving), dedicated and integrated; no callback for avalonia (Avalonia's
       first adapter) or in an ARM64 process, where any callback replaces Avalonia's Adreno rule. The callback applies
       only to ANGLE on Direct3D 11: with wgl, OpenGL first, it runs only when OpenGL is unavailable. */
    private static Win32PlatformOptions CreateWin32PlatformOptions(string mode)
    {
        Win32RenderingMode[] angle = { Win32RenderingMode.AngleEgl, Win32RenderingMode.Software };
        Win32CompositionMode[] composition;
        Win32RenderingMode[] rendering = angle;
        switch (mode)
        {
        case null:
            composition = CreateDefaultWinComposition();
            break;
        case "avalonia":
            return null;
        case "winui":
            composition = new[] { Win32CompositionMode.WinUIComposition, Win32CompositionMode.RedirectionSurface };
            break;
        case "dcomp":
            composition = new[] { Win32CompositionMode.DirectComposition, Win32CompositionMode.RedirectionSurface };
            break;
        case "dxgi":
            composition = new[] { Win32CompositionMode.LowLatencyDxgiSwapChain, Win32CompositionMode.RedirectionSurface };
            break;
        case "redirect":
            composition = new[] { Win32CompositionMode.RedirectionSurface };
            break;
        case "wgl":
            composition = new[] { Win32CompositionMode.RedirectionSurface };
            rendering = new[] { Win32RenderingMode.Wgl, Win32RenderingMode.AngleEgl, Win32RenderingMode.Software };
            break;
        default:
            Console.Error.WriteLine("GnollHack: unknown Windows composition mode \"" + mode + "\"; using the default");
            composition = CreateDefaultWinComposition();
            break;
        }
        return new Win32PlatformOptions
        {
            RenderingMode = rendering,
            CompositionMode = composition,
            OverlayPopups = true,
        };
    }

    // WORKAROUND(WA-STEAM-0003): Steam's overlay draws only on a window swap chain's Present
    /* Steam's overlay draws when a window swap chain presents; over WinUI composition it draws nothing */
    private static Win32CompositionMode[] CreateDefaultWinComposition()
    {
        return new[]
        {
            Win32CompositionMode.LowLatencyDxgiSwapChain,
            Win32CompositionMode.WinUIComposition,
            Win32CompositionMode.RedirectionSurface,
        };
    }

#if WINDOWS_AVALONIA
    /* The options with the adapter selection callback of the requested GPU mode (see CreateWin32PlatformOptions);
       options unchanged for avalonia and in an ARM64 process */
    private static Win32PlatformOptions AddGpuSelection(Win32PlatformOptions options, string gpu)
    {
        if (gpu == "avalonia")
            return options;
        if (RuntimeInformation.ProcessArchitecture == Architecture.Arm64)
        {
            Console.Error.WriteLine("GnollHack: Windows GPU selection off on ARM64; using Avalonia's choice");
            return options;
        }
        GHWindowsGpuMode gpuMode = GHWindowsGpuMode.Auto;
        if (gpu != null && !GHWindowsGpuChoice.TryParseMode(gpu, out gpuMode))
        {
            Console.Error.WriteLine("GnollHack: unknown Windows GPU mode \"" + gpu + "\"; using auto");
            gpuMode = GHWindowsGpuMode.Auto;
        }
        if (options == null)
            options = new Win32PlatformOptions();
        options.GraphicsAdapterSelectionCallback = GHWindowsGpuSelection.CreateCallback(gpuMode);
        return options;
    }
#endif

    /* Windows: the type name of the render timer Avalonia applied, such as DxgiConnection or SleepLoopRenderTimer;
       null until Avalonia's setup is done */
    internal static string WindowsRenderTimerName { get; private set; }

    /* After Avalonia's setup, when the render loop and graphics are bound: the requested mode, the render timer that
       shows which composition mode was applied, the platform graphics, on Windows Avalonia the requested GPU mode and
       the adapter GHWindowsGpuSelection chose ("not selected" when its callback has not run), and whether Steam's
       overlay renderer is in the process, now and once more after SteamOverlayRecheckMs, since Steam may inject it
       after the start */
    private static void LogWindowsGraphics(string requestedMode, string requestedGpu)
    {
        WindowsRenderTimerName = GetLocatorServiceTypeName("Avalonia.Rendering.IRenderLoop, Avalonia.Base", "Timer");
        string line = "GnollHack: Windows composition request " + (requestedMode ?? "default")
            + "; render timer " + WindowsRenderTimerName
            + "; platform graphics " + GetLocatorServiceTypeName("Avalonia.Platform.IPlatformGraphics, Avalonia.Base", null);
#if WINDOWS_AVALONIA
        line += "; GPU request " + (requestedGpu ?? "default") + "; GPU " + GHWindowsGpuSelection.Summary;
#endif
        Console.Error.WriteLine(line);
        LogSteamOverlay();
        _steamOverlayRecheck = new System.Threading.Timer(state => LogSteamOverlay(), null, SteamOverlayRecheckMs, System.Threading.Timeout.Infinite);
    }

    private static void LogSteamOverlay()
    {
        bool present = GHAvaloniaSteamOverlay.IsPresent;
        Console.Error.WriteLine("GnollHack: Steam overlay renderer " + (present ? "loaded" : "not loaded"));
    }

    /* The type name of an AvaloniaLocator service, or of its property; AvaloniaLocator is internal in the reference
       assemblies. Never throws. */
    private static string GetLocatorServiceTypeName(string serviceTypeName, string propertyName)
    {
        const BindingFlags staticFlags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static;
        const BindingFlags instanceFlags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance;
        try
        {
            Type locatorType = Type.GetType("Avalonia.AvaloniaLocator, Avalonia.Base", true);
            object locator = locatorType.GetProperty("Current", staticFlags)?.GetValue(null);
            if (locator == null)
                return "unknown (no locator)";
            MethodInfo getService = locator.GetType().GetMethod("GetService", instanceFlags, null, new Type[] { typeof(Type) }, null);
            if (getService == null)
                return "unknown (no GetService)";
            object service = getService.Invoke(locator, new object[] { Type.GetType(serviceTypeName, true) });
            if (service != null && propertyName != null)
                service = service.GetType().GetProperty(propertyName, instanceFlags)?.GetValue(service);
            return service == null ? "none" : service.GetType().Name;
        }
        catch (Exception ex)
        {
            Exception inner = ex is TargetInvocationException && ex.InnerException != null ? ex.InnerException : ex;
            return "unknown (" + inner.GetType().Name + ": " + inner.Message + ")";
        }
    }

    /* The FMOD wrappers import "fmod" and "fmodstudio". libfmodstudio.so.14 loads its core library by soname,
       libfmod.so.14, from its own directory; loading the core under any other file name would create a
       second FMOD instance, in which the Studio system's core handle is invalid. GHSentryNative and
       GHAvaloniaSentryNative import "sentry", always the application's own libsentry.so, never a system one. */
    private static IntPtr ResolveLinuxLibrary(string libraryName, Assembly assembly, DllImportSearchPath? searchPath)
    {
        string fileName;
        if (libraryName == "fmod")
            fileName = "libfmod.so.14";
        else if (libraryName == "fmodstudio")
            fileName = "libfmodstudio.so.14";
#if SENTRY
        else if (libraryName == "sentry")
            fileName = "libsentry.so";
#endif
        else
            return IntPtr.Zero;

        return NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory, fileName));
    }

    /* macOS: Metal, then OpenGL, then software; OpenGL, then software when the Metal Rendering setting is off.
       GNOLLHACK_MAC_RENDERING overrides the setting: =metal starts at Metal, =opengl at OpenGL, =software uses only
       software rendering. Essentials are installed here, before Avalonia starts, to read the setting. */
    private static AvaloniaNativeRenderingMode[] GetMacRenderingModes()
    {
        AvaloniaNativeRenderingMode[] metalFirst = { AvaloniaNativeRenderingMode.Metal, AvaloniaNativeRenderingMode.OpenGl, AvaloniaNativeRenderingMode.Software };
        AvaloniaNativeRenderingMode[] openGlFirst = { AvaloniaNativeRenderingMode.OpenGl, AvaloniaNativeRenderingMode.Software };

        string mode = Environment.GetEnvironmentVariable("GNOLLHACK_MAC_RENDERING");
        if (string.Equals(mode, "metal", StringComparison.OrdinalIgnoreCase))
            return metalFirst;
        if (string.Equals(mode, "opengl", StringComparison.OrdinalIgnoreCase))
            return openGlFirst;
        if (string.Equals(mode, "software", StringComparison.OrdinalIgnoreCase))
            return new[] { AvaloniaNativeRenderingMode.Software };

        if (!OperatingSystem.IsMacOS())
            return metalFirst;
        try
        {
            GHAvaloniaEssentials.InstallEarly();
            bool metal = Microsoft.Maui.Storage.Preferences.Default.Get("UseMetal", GHConstants.DefaultUseMetalRenderingMac);
            return metal ? metalFirst : openGlFirst;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("GnollHack: reading Metal Rendering failed: " + ex.Message);
            return metalFirst;
        }
    }

    /* The FMOD wrappers import "fmod" and "fmodstudio". libfmodstudio.dylib refers to its core library by install
       name; libfmod.dylib is loaded from the application directory first, so that the dynamic loader uses that
       image rather than searching for one. GHSentryNative imports "gnhsentry", always the application's own
       libgnhsentry.dylib. */
    private static IntPtr ResolveMacLibrary(string libraryName, Assembly assembly, DllImportSearchPath? searchPath)
    {
        string core = Path.Combine(AppContext.BaseDirectory, "libfmod.dylib");
        if (libraryName == "fmod")
            return NativeLibrary.Load(core);
        if (libraryName == "fmodstudio")
        {
            NativeLibrary.Load(core);
            return NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory, "libfmodstudio.dylib"));
        }
#if SENTRY
        if (libraryName == "gnhsentry")
            return NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory, "libgnhsentry.dylib"));
#endif
        return IntPtr.Zero;
    }

#if LINUX
    private const int RTLD_NOW = 2;

    [DllImport("libc", EntryPoint = "dlopen")]
    private static extern IntPtr DlOpen(string fileName, int flags);

    [DllImport("libc", EntryPoint = "dlerror")]
    private static extern IntPtr DlError();

    // WORKAROUND(WA-SKIASHARP-0009): libHarfBuzzSharp binds its own calls to the system HarfBuzz
    /* libHarfBuzzSharp calls its own exported hb_* functions through the PLT. FreeType 2.14 and later load the
       system libharfbuzz.so.0 with RTLD_GLOBAL when fontconfig scans font files, and a call bound lazily after that
       resolves to the system HarfBuzz, which then aborts on HarfBuzzSharp's objects. RTLD_NOW binds every call to
       libHarfBuzzSharp itself before anything can load the system copy; HarfBuzzSharp's own load later gets this one. */
    private static void PreloadHarfBuzzSharp()
    {
        try
        {
            string path = Path.Combine(AppContext.BaseDirectory, "libHarfBuzzSharp.so");
            if (!File.Exists(path))
                return;
            if (DlOpen(path, RTLD_NOW) == IntPtr.Zero)
            {
                IntPtr error = DlError();
                Console.Error.WriteLine("AvaloniaDesktopProgram: cannot preload libHarfBuzzSharp.so: "
                    + (error != IntPtr.Zero ? Marshal.PtrToStringAnsi(error) : "unknown error"));
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("AvaloniaDesktopProgram: cannot preload libHarfBuzzSharp.so: " + ex.Message);
        }
    }
#endif
}
